<template><main class="admin-core-page mx-auto max-w-[1500px] px-4 py-6 md:px-7 md:py-7"><AdminSalesWorkflow /><NuxtLink to="/admin/accounting" class="text-sm font-bold text-blue-600">← Accounting</NuxtLink><div class="mt-2 flex flex-wrap justify-between gap-3"><div><h1 class="text-3xl font-black">Sales & Invoices</h1><p class="text-slate-500">Invoices, receivables and customer payments.</p></div><button class="btn-secondary" @click="load">Refresh</button></div><div v-if="msg" class="my-4 rounded-lg bg-slate-100 p-3">{{msg}}</div>
<section v-if="unposted.length" class="admin-panel mt-5 p-5"><h2 class="text-xl font-black">Historical / Unposted Orders</h2><p class="mt-1 text-sm text-amber-700"><b>Not posted automatically.</b> Post only orders you want included in Kialla Accounting.</p><div class="mt-3 overflow-x-auto"><table class="w-full text-sm"><thead><tr class="border-b text-left"><th class="p-2">Order</th><th>Date</th><th>Customer</th><th class="text-right">Total</th><th></th></tr></thead><tbody><tr v-for="o in unposted" :key="o.id" class="border-b"><td class="p-2 font-bold">#{{o.id}}</td><td>{{date(o.created_at)}}</td><td>{{o.customer_name||o.customer_email}}</td><td class="text-right">{{money(o.total)}}</td><td class="text-right"><button class="btn-primary" @click="postOrder(o)">Post</button></td></tr></tbody></table></div></section>
<section class="admin-panel mt-5 p-5"><div class="flex justify-between gap-3"><div><h2 class="text-xl font-black">Accounting Invoices</h2><p class="text-sm text-slate-500">Record full or partial payments against unpaid invoices.</p></div><div class="text-right"><div class="text-xs font-bold uppercase text-slate-500">Outstanding</div><div class="text-xl font-black">{{money(outstanding)}}</div></div></div><div class="mt-4 overflow-x-auto"><table class="w-full text-sm"><thead><tr class="border-b text-left"><th class="p-2">Invoice</th><th>Date</th><th>Customer</th><th>Status</th><th class="text-right">Total</th><th class="text-right">Paid</th><th class="text-right">Balance</th><th></th></tr></thead><tbody><tr v-for="i in invoices" :key="i.id" class="border-b"><td class="p-2 font-bold">{{i.invoice_number}}</td><td>{{i.invoice_date}}</td><td>{{i.customer_name||i.customer_email||'—'}}</td><td><span class="rounded-full bg-slate-100 px-2 py-1 text-xs font-bold uppercase">{{label(i.status)}}</span></td><td class="text-right">{{money(i.total)}}</td><td class="text-right text-emerald-700">{{money(i.paid_amount)}}</td><td class="text-right font-bold">{{money(balance(i))}}</td><td class="text-right"><button v-if="balance(i)>0" class="btn-primary" @click="openPayment(i)">Record Payment</button><button class="ml-2 text-xs font-bold text-blue-600" @click="toggleHistory(i)">History</button></td></tr><tr v-if="!invoices.length"><td colspan="8" class="p-8 text-center text-slate-500">No accounting invoices yet.</td></tr></tbody></table></div></section>
<div v-if="paymentInvoice" class="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4" @click.self="paymentInvoice=null"><div class="w-full max-w-lg rounded-2xl bg-white p-6 shadow-xl"><div class="flex justify-between"><div><h2 class="text-xl font-black">Record Payment</h2><p class="text-sm text-slate-500">{{paymentInvoice.invoice_number}} · Balance {{money(balance(paymentInvoice))}}</p></div><button class="text-2xl" @click="paymentInvoice=null">×</button></div><div class="mt-5 grid gap-4 sm:grid-cols-2"><label class="text-sm font-bold">Amount<input v-model.number="form.amount" type="number" min="0.01" step="0.01" class="field"></label><label class="text-sm font-bold">Payment Date<input v-model="form.payment_date" type="date" class="field"></label><label class="text-sm font-bold">Method<select v-model="form.payment_method" class="field"><option>Bank Transfer</option><option>EFTPOS</option><option>Cash</option><option>Stripe</option><option>Other</option></select></label><label class="text-sm font-bold">Reference<input v-model="form.reference" class="field" placeholder="Receipt / bank reference"></label><label class="text-sm font-bold sm:col-span-2">Notes<textarea v-model="form.notes" class="field" rows="3"></textarea></label></div><div class="mt-5 flex justify-end gap-2"><button class="btn-secondary" @click="paymentInvoice=null">Cancel</button><button class="btn-primary" :disabled="saving" @click="savePayment">{{saving?'Saving…':'Record Payment'}}</button></div></div></div>
<div v-if="historyInvoice" class="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4" @click.self="historyInvoice=null"><div class="w-full max-w-2xl rounded-2xl bg-white p-6 shadow-xl"><div class="flex justify-between"><div><h2 class="text-xl font-black">Payment History</h2><p class="text-sm text-slate-500">{{historyInvoice.invoice_number}}</p></div><button class="text-2xl" @click="historyInvoice=null">×</button></div><div v-if="historyLoading" class="py-8 text-center">Loading…</div><div v-else class="mt-4 divide-y"><div v-for="p in payments" :key="p.id" class="grid grid-cols-[1fr_auto] gap-3 py-3"><div><b>{{date(p.payment_date)}}</b> · {{p.payment_method}}<div class="text-xs text-slate-500">{{p.reference||'No reference'}}<span v-if="p.notes"> · {{p.notes}}</span></div></div><b>{{money(p.amount)}}</b></div><p v-if="!payments.length" class="py-8 text-center text-slate-500">No payments recorded.</p></div></div></div></main></template>
<script setup lang="ts">
const dialog = useAppDialog();definePageMeta({layout:"admin",middleware:["admin"]});const{adminFetch}=useAdminFetch(),invoices=ref<any[]>([]),unposted=ref<any[]>([]),msg=ref(""),paymentInvoice=ref<any>(null),historyInvoice=ref<any>(null),payments=ref<any[]>([]),historyLoading=ref(false),saving=ref(false);const form=reactive({amount:0,payment_date:new Date().toISOString().slice(0,10),payment_method:"Bank Transfer",reference:"",notes:""});const money=(v:any)=>new Intl.NumberFormat("en-AU",{style:"currency",currency:"AUD"}).format(Number(v||0)),date=(v:any)=>new Date(v).toLocaleDateString("en-AU"),balance=(i:any)=>Math.max(0,Number(i.total||0)-Number(i.paid_amount||0)),label=(s:any)=>String(s||"unpaid").replace("_"," ");const outstanding=computed(()=>invoices.value.reduce((n,i)=>n+balance(i),0));async function load(){[invoices.value,unposted.value]=await Promise.all([adminFetch("/api/admin/accounting/invoices"),adminFetch("/api/admin/accounting/unposted-orders")])}function openPayment(i:any){paymentInvoice.value=i;form.amount=balance(i);form.payment_date=new Date().toISOString().slice(0,10);form.payment_method="Bank Transfer";form.reference="";form.notes=""}async function savePayment(){if(!paymentInvoice.value)return;saving.value=true;try{await adminFetch("/api/admin/accounting/customer-payments",{method:"POST",body:{invoice_id:paymentInvoice.value.id,...form}});msg.value=`Payment recorded against ${paymentInvoice.value.invoice_number}.`;paymentInvoice.value=null;await load()}catch(e:any){msg.value=e?.data?.statusMessage||e.message}finally{saving.value=false}}async function toggleHistory(i:any){historyInvoice.value=i;historyLoading.value=true;try{payments.value=await adminFetch(`/api/admin/accounting/customer-payments?invoice_id=${i.id}`)}finally{historyLoading.value=false}}async function postOrder(o:any){if(!await dialog.confirm(`Post Order #${o.id} to accounting? This creates a permanent invoice and journal.`))return;try{const x:any=await adminFetch("/api/admin/accounting/post-order",{method:"POST",body:{order_id:o.id}});msg.value=`${x.invoice_number||"Invoice"} posted.`;await load()}catch(e:any){msg.value=e?.data?.statusMessage||e.message}}onMounted(load)</script>
<style scoped>.admin-panel{@apply rounded-xl border border-slate-200 bg-white shadow-sm}.btn-primary{@apply rounded-lg bg-blue-600 px-4 py-2 text-sm font-bold text-white disabled:opacity-50}.btn-secondary{@apply rounded-lg border border-slate-300 bg-white px-4 py-2 text-sm font-bold}.field{@apply mt-1 block w-full rounded-lg border border-slate-300 px-3 py-2 font-normal}</style>
